// Guards the committed Android launcher icons and the adaptive-icon vectors.
//
// The PNGs are generated by `tool/export_brand_icons.dart` and committed
// because Android needs them at build time. This test is the gate that catches
// drift: a missing icon, a wrong size, or an icon that is not the wind mark
// fails the normal `flutter test` suite instead of being noticed on a phone.
//
// The hand-written vector layers are guarded too, because the PNGs are only the
// API < 26 path. A brand edit that updated `brand/logo/icon.svg` and the
// exporter would regenerate every PNG and still pass while the API >= 26
// foreground silently kept the old mark — so the same ribbon `d` strings and
// the same palette are asserted against the drawables.
//
// Run on its own with:
//
//     flutter test test/brand/launcher_icon_test.dart
import 'dart:io';
import 'dart:math' as math;
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';

import '../../tool/export_brand_icons.dart';

/// The adaptive-icon foreground layer.
const String foregroundPath =
    '$resourceRoot/drawable/ic_launcher_foreground.xml';

/// The adaptive-icon monochrome (themed-icon) layer.
const String monochromePath =
    '$resourceRoot/drawable/ic_launcher_monochrome.xml';

/// Per-channel slack allowed when comparing a committed PNG with a fresh
/// render. Both go through the same lossless path, so this only absorbs
/// antialiasing that a different `dart:ui` engine build might round differently.
const int channelTolerance = 8;

/// The fill every path in the monochrome layer must use. The layer is a
/// silhouette: Android 13+ tints its alpha, so it stays one flat colour.
const String monochromeFill = '#FFFFFFFF';

/// `0xRRGGBB` for an opaque brand colour, as it appears in the SVG and the XML.
String _hex(int argb) =>
    '#${(argb & 0xFFFFFF).toRadixString(16).padLeft(6, '0').toUpperCase()}';

/// `0xAARRGGBB`, for failure messages.
String _argb(int value) => '0x${value.toRadixString(16).padLeft(8, '0')}';

/// True when [a] and [b] agree on every 8-bit channel within [tolerance].
bool _withinTolerance(int a, int b, int tolerance) {
  for (int shift = 0; shift <= 24; shift += 8) {
    if ((((a >> shift) & 0xFF) - ((b >> shift) & 0xFF)).abs() > tolerance) {
      return false;
    }
  }
  return true;
}

/// Renders the wind mark in-process and compares it with [icon] pixel by pixel
/// on a sampled grid, so a half-drawn or partly-wrong artwork fails instead of
/// passing on a handful of lucky samples.
Future<void> _expectMatchesRenderedMark(
  DecodedIcon icon,
  int size,
  String label,
) async {
  final DecodedIcon mark = await decodePng(await renderLegacyTile(size));
  expect(icon.width, mark.width, reason: '$label: width');
  expect(icon.height, mark.height, reason: '$label: height');

  final int step = math.max(1, size ~/ 24);
  int compared = 0;
  for (int y = 0; y < size; y += step) {
    for (int x = 0; x < size; x += step) {
      final int actual = icon.argbAt(x, y);
      final int expected = mark.argbAt(x, y);
      if (!_withinTolerance(actual, expected, channelTolerance)) {
        fail(
          '$label: pixel ($x, $y) is ${_argb(actual)} but the wind mark '
          'renders ${_argb(expected)} — the committed icon is not the mark; '
          'run `flutter test tool/export_brand_icons.dart` to regenerate it',
        );
      }
      compared++;
    }
  }
  // A sampling bug that compares nothing must not look like a pass.
  expect(compared, greaterThan(100), reason: '$label: too few pixels compared');
}

/// Every `android:pathData="..."` value in [xml], in document order.
List<String> _pathDataIn(String xml) => RegExp(
  r'android:pathData="([^"]*)"',
).allMatches(xml).map((RegExpMatch match) => match.group(1)!).toList();

/// Every `android:fillColor="..."` value in [xml], in document order.
List<String> _fillColorsIn(String xml) => RegExp(
  r'android:fillColor="([^"]*)"',
).allMatches(xml).map((RegExpMatch match) => match.group(1)!).toList();

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  test('every legacy density PNG is sized and matches the wind mark', () async {
    for (final IconBucket bucket in iconBuckets) {
      final String path = '$resourceRoot/${bucket.directory}/ic_launcher.png';
      final File file = File(path);
      expect(
        file.existsSync(),
        isTrue,
        reason:
            '$path is missing — run '
            '`flutter test tool/export_brand_icons.dart` to regenerate it',
      );

      final Uint8List bytes = file.readAsBytesSync();
      final DecodedIcon icon = await decodePng(bytes);
      expect(icon.width, bucket.size, reason: '$path: width');
      expect(icon.height, bucket.size, reason: '$path: height');
      await _expectMatchesRenderedMark(icon, bucket.size, path);
    }
  });

  test('the exporter geometry is copied verbatim from brand/logo/icon.svg', () {
    final String svg = File('brand/logo/icon.svg').readAsStringSync();

    for (final WindRibbon ribbon in windRibbons) {
      expect(
        svg,
        contains(ribbon.pathData),
        reason:
            'the exporter ribbon "${ribbon.pathData}" no longer appears in '
            'brand/logo/icon.svg — update tool/export_brand_icons.dart and '
            'regenerate the PNGs',
      );
      expect(
        svg,
        contains(_hex(ribbon.argb)),
        reason: 'ribbon colour ${_hex(ribbon.argb)} is not in icon.svg',
      );
    }

    expect(
      svg,
      contains(_hex(tileColorArgb)),
      reason: 'the tile colour ${_hex(tileColorArgb)} is not in icon.svg',
    );
  });

  test('the adaptive icon vectors repeat the same geometry and palette', () {
    final String foreground = File(foregroundPath).readAsStringSync();
    final String monochrome = File(monochromePath).readAsStringSync();
    final List<String> markPaths = windRibbons
        .map((WindRibbon ribbon) => ribbon.pathData)
        .toList();
    final List<String> markFills = windRibbons
        .map((WindRibbon ribbon) => _hex(ribbon.argb))
        .toList();

    // Geometry: both layers draw the same ribbons, in the same order.
    for (final String path in <String>[foregroundPath, monochromePath]) {
      expect(
        _pathDataIn(File(path).readAsStringSync()),
        markPaths,
        reason:
            '$path no longer draws the wind mark — copy the `d` strings from '
            'brand/logo/icon.svg and keep the two layers identical',
      );
    }

    // Palette: the foreground carries the three brand fills, in ribbon order.
    expect(
      _fillColorsIn(foreground),
      markFills,
      reason:
          '$foregroundPath no longer carries the brass/ink/grey palette from '
          'brand/logo/icon.svg',
    );

    // The monochrome layer is a silhouette by design: one flat fill and no
    // background, because Android tints its alpha for themed icons.
    expect(
      _fillColorsIn(monochrome).toSet(),
      <String>{monochromeFill},
      reason:
          '$monochromePath must stay a single-colour silhouette '
          '($monochromeFill) so Android 13+ can tint it',
    );
    expect(
      monochrome,
      isNot(contains('<rect')),
      reason: '$monochromePath must not carry a background layer',
    );
  });

  test('the vector group maps the 64-unit grid into the central 72dp', () {
    for (final String path in <String>[foregroundPath, monochromePath]) {
      final String xml = File(path).readAsStringSync();
      expect(xml, contains('android:scaleX="1.125"'), reason: '$path: scaleX');
      expect(xml, contains('android:scaleY="1.125"'), reason: '$path: scaleY');
      expect(
        xml,
        contains('android:translateX="18"'),
        reason: '$path: translateX',
      );
      expect(
        xml,
        contains('android:translateY="18"'),
        reason: '$path: translateY',
      );
    }
  });
}
